#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // The original binary expects exactly two arguments after the program name:
    //   1) an integer shift (can be signed)
    //   2) a text string to be Caesar‑shifted.
    // If the requirements are not met it prints "USAGE" and exits.
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    // Validate and parse the shift value.
    char *endptr = NULL;
    long shift = strtol(argv[1], &endptr, 10);
    // strtol accepts an optional leading '+' or '-'.  The original code also
    // performed a manual check that the whole argument consists of a sign
    // followed only by decimal digits.  We replicate that behaviour.
    if (endptr == argv[1] || *endptr != '\0') {
        puts("USAGE");
        return 0;
    }

    // Normalise the shift to the range 0‑25 (the original program works modulo 26).
    int s = (int)(shift % 26);
    if (s < 0) s += 26;

    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) { // the binary aborts for strings longer than 0x400 bytes
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (c >= 'A' && c <= 'Z') {
            putchar(((c - 'A' + s) % 26) + 'A');
        } else if (c >= 'a' && c <= 'z') {
            putchar(((c - 'a' + s) % 26) + 'a');
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
